  const _component_TinyLLMMap = resolveComponent("TinyLLMMap");
  _push(`<div${ssrRenderAttrs(_attrs)}><h1 id="第-10-章-初始化与残差路径" tabindex="-1">第 10 章：初始化与残差路径 <a class="header-anchor" href="#第-10-章-初始化与残差路径" aria-label="Permalink to &quot;第 10 章：初始化与残差路径&quot;">​</a></h1><p><a href="./">课程总览</a> · <a href="./transformer-block.html">上一章</a> · <a href="./normalization.html">下一章</a></p><div class="tip custom-block"><p class="custom-block-title">本章学习目标</p><p>能根据权重形状找出 <code>fan_in</code>、<code>fan_out</code>，并估算一个线性层输出的尺度；能写出残差子层的前向式和反向梯度；能用每层激活 RMS 和梯度范数判断一个多层网络在起点是否异常。</p><p><strong>前置：</strong> <a href="./tensors-and-autograd.html">第 2 章</a>的张量形状与自动求导；知道 Block 由注意力和前馈层两个子层组成（<a href="./self-attention.html">第 6 章</a>、<a href="./activations-and-ffn.html">第 8 章</a>、<a href="./transformer-block.html">第 9 章</a>）。</p><p><strong>实践方式：</strong> <a href="/tinyllm/notebooks/initialization-and-residuals.html">initialization-and-residuals.ipynb</a>（也可以直接运行 <a href="/tinyllm/code/initialization-and-residuals.py" download>initialization-and-residuals.py</a>），CPU 即可，图表使用 Plotly。</p></div>`);
